<?php
namespace App\Services;use App\Models\{Service,ServiceCategory};use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class ServiceManagementService{public function create(array $d,$admin):Service{return Service::create($d+['id'=>(string)Str::uuid(),'created_by'=>$admin->id]);}public function update(Service $s,array $d):Service{$s->update($d);return $s->fresh(['category','media']);}public function delete(Service $s):void{$s->delete();}public function publicList(array $q){$x=Service::where('status','ACTIVE')->with(['category','media']);if(!empty($q['category_id']))$x->where('category_id',$q['category_id']);if(!empty($q['search']))$x->where(fn($w)=>$w->where('title','like','%'.$q['search'].'%')->orWhere('short_description','like','%'.$q['search'].'%')->orWhere('description','like','%'.$q['search'].'%'));return $x->latest()->paginate(min((int)($q['limit']??20),50));}}
